with order_summary as (select order_id, count(cost) as cost_count, count(distinct cost) as unique_carriers from shipments where status = 'IN_TRANSIT' group by order_id) select orders.id, orders.status, order_summary.cost_count, order_summary.unique_carriers from orders inner join order_summary on orders.id = order_summary.order_id where order_summary.cost_count > 8 order by 1 limit 5;
